/// C01.09 — instructor-side simulator core.
/// SEMANTIC_RECONSTRUCTION: original bytes lost; behavior rebuilt to make
/// the historically claimed claim measurable. Bounded difference documented
/// in 00-recovery-provenance.md.
library;


const dbTable = {
  '1': 'سعاد حسن',
  '2': 'محمود فتحي',
};

List<String> httpRequest(String method, String path) {
  final lines = <String>[
    'REQUEST $method $path HTTP/1.1',
  ];
  if (method == 'GET' && path == '/api/patients/2') {
    lines.add('API routes to db lookup key=2');
    lines.add('DB_ROW=${dbTable["2"]}');
    lines.add('RESPONSE 200 OK json={"id":2,"name":"${dbTable['2']}}"}');
  } else if (path == '/api/nope') {
    lines.add('RESPONSE 404 NOT FOUND');
  } else {
    lines.add('RESPONSE 400 BAD REQUEST');
  }
  return lines;
}
